'use client';

import { useEffect, useRef, useState } from 'react';
import {
  createWebSessionMonitor,
  type WebSessionMonitor,
  type WebSessionSnapshot,
} from '@niwar-devforge/web-session-core';

interface Profile {
  id: string;
  email: string;
  display_name: string | null;
}

const initialSnapshot: WebSessionSnapshot<Profile> = {
  status: 'idle',
  profile: null,
  source: null,
  checkedAtMs: null,
  errorCode: null,
};

export function AuthPanel() {
  const [snapshot, setSnapshot] = useState(initialSnapshot);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [message, setMessage] = useState<string | null>(null);
  const monitorRef = useRef<WebSessionMonitor<Profile> | null>(null);

  useEffect(() => {
    const monitor = createWebSessionMonitor<Profile>({
      onChange: setSnapshot,
    });
    monitorRef.current = monitor;
    monitor.start();
    return () => {
      monitor.stop();
      monitorRef.current = null;
    };
  }, []);

  async function sendCredentials(path: '/api/auth/register' | '/api/auth/login') {
    setMessage(null);
    const response = await fetch(path, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      credentials: 'same-origin',
      cache: 'no-store',
      body: JSON.stringify(
        path.endsWith('register')
          ? { email, password, display_name: '{{PRODUCT_NAME}} User' }
          : { identifier: email, password },
      ),
    });
    const body = (await response.json()) as Record<string, unknown>;
    if ('session_token' in body) throw new Error('unsafe browser-visible session token');
    if (!response.ok) {
      setMessage(typeof body.code === 'string' ? body.code : 'request_failed');
      return;
    }
    if (path.endsWith('login')) await monitorRef.current?.revalidate('auth-change');
    setMessage(path.endsWith('register') ? 'registered' : 'authenticated');
  }

  async function logout() {
    setMessage(null);
    const response = await fetch('/api/auth/logout', {
      method: 'DELETE',
      credentials: 'same-origin',
      cache: 'no-store',
    });
    if (!response.ok && response.status !== 204) {
      setMessage('logout_failed');
      return;
    }
    await monitorRef.current?.revalidate('auth-change');
    setMessage('logged_out');
  }

  return (
    <section>
      <p className="status" data-testid="session-status">{snapshot.status}</p>
      {snapshot.profile ? <p data-testid="signed-in-email">{snapshot.profile.email}</p> : null}
      <form onSubmit={(event) => event.preventDefault()}>
        <label>
          Email
          <input data-testid="email" type="email" value={email} onChange={(event) => setEmail(event.target.value)} />
        </label>
        <label>
          Password
          <input data-testid="password" type="password" value={password} onChange={(event) => setPassword(event.target.value)} />
        </label>
        <button data-testid="register" type="button" onClick={() => void sendCredentials('/api/auth/register')}>Register</button>
        <button data-testid="login" type="button" onClick={() => void sendCredentials('/api/auth/login')}>Login</button>
        <button data-testid="logout" type="button" onClick={() => void logout()}>Logout</button>
      </form>
      {message ? <p data-testid="message">{message}</p> : null}
      {snapshot.status === 'error' ? <p className="error">Session revalidation failed.</p> : null}
    </section>
  );
}

