import { createWebAuthBff } from '@niwar-devforge/web-bff-core';

const configuredPublicOrigin = process.env.DEVFORGE_PRODUCT_PUBLIC_ORIGIN;
const configuredBackendApiBaseUrl = process.env.DEVFORGE_PRODUCT_BACKEND_API_BASE_URL;
const trustIngressClientAddress = process.env.DEVFORGE_PRODUCT_TRUST_INGRESS_CLIENT_IP === '1';

if (process.env.NODE_ENV === 'production' && (!configuredPublicOrigin || !configuredBackendApiBaseUrl)) {
  throw new Error('production requires DEVFORGE_PRODUCT_PUBLIC_ORIGIN and DEVFORGE_PRODUCT_BACKEND_API_BASE_URL');
}

const publicOrigin = configuredPublicOrigin ?? 'http://127.0.0.1:3000';
const backendApiBaseUrl = configuredBackendApiBaseUrl ?? 'http://127.0.0.1:8000/api/v1';
const secureCookie = publicOrigin.startsWith('https://');

if (trustIngressClientAddress && !secureCookie) {
  throw new Error('trusted ingress client-address mode requires an https public origin');
}

export const productBff = createWebAuthBff({
  publicOrigin,
  backendApiBaseUrl,
  cookieName: secureCookie ? '__Host-devforge_session' : 'devforge_session',
  secureCookie,
  ...(trustIngressClientAddress
    ? {
        resolveTrustedClientAddress: async (request: Request) =>
          request.headers.get('x-devforge-ingress-client-ip'),
      }
    : {}),
});

